#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

#define MAX_SESSIONS 64
#define TOKEN_LEN 32
#define MAX_HANDLERS 8

typedef struct session {
    int refcount;
    uint32_t session_id;
    char token[TOKEN_LEN];
    char user_data[256];
    int active;
} session_t;

typedef struct session_pool {
    session_t sessions[MAX_SESSIONS];
    int allocated[MAX_SESSIONS];
    int next_id;
} session_pool_t;

static session_pool_t g_pool;

typedef int (*event_handler_t)(session_t *sess, int event_type, void *data);

static event_handler_t g_handlers[MAX_HANDLERS];
static int g_handler_count = 0;

void pool_init(void) {
    memset(&g_pool, 0, sizeof(g_pool));
    g_pool.next_id = 1;
}

session_t *session_alloc(void) {
    for (int i = 0; i < MAX_SESSIONS; i++) {
        if (!g_pool.allocated[i]) {
            g_pool.allocated[i] = 1;
            memset(&g_pool.sessions[i], 0, sizeof(session_t));
            g_pool.sessions[i].session_id = g_pool.next_id++;
            g_pool.sessions[i].refcount = 1;
            g_pool.sessions[i].active = 1;
            return &g_pool.sessions[i];
        }
    }
    return NULL;
}

void session_ref(session_t *sess) {
    if (sess) sess->refcount++;
}

void session_unref(session_t *sess) {
    if (!sess) return;
    sess->refcount--;
    if (sess->refcount <= 0) {
        int idx = (int)(sess - g_pool.sessions);
        if (idx >= 0 && idx < MAX_SESSIONS) {
            memset(sess->user_data, 0, sizeof(sess->user_data));
            memset(sess->token, 0, TOKEN_LEN);
            sess->active = 0;
            sess->session_id = 0;
            g_pool.allocated[idx] = 0;
        }
    }
}

session_t *session_find_by_id(uint32_t id) {
    for (int i = 0; i < MAX_SESSIONS; i++) {
        if (g_pool.allocated[i] && g_pool.sessions[i].session_id == id) {
            session_ref(&g_pool.sessions[i]);
            return &g_pool.sessions[i];
        }
    }
    return NULL;
}

int register_handler(event_handler_t handler) {
    if (g_handler_count >= MAX_HANDLERS) return -1;
    g_handlers[g_handler_count++] = handler;
    return 0;
}

/* Dispatches event to all handlers. On error from any handler,
 * stops dispatching and returns the error code.
 * The session reference is NOT consumed by this function -
 * caller retains ownership. */
int dispatch_event(session_t *sess, int event_type, void *data) {
    int rc = 0;
    for (int i = 0; i < g_handler_count; i++) {
        rc = g_handlers[i](sess, event_type, data);
        if (rc < 0) {
            return rc;
        }
    }
    return 0;
}

/* Validates token format - returns 0 if valid */
int validate_token(const char *token, size_t len) {
    if (len == 0 || len > TOKEN_LEN) return -1;
    for (size_t i = 0; i < len; i++) {
        char c = token[i];
        if (!((c >= 'a' && c <= 'f') || (c >= '0' && c <= '9'))) return -1;
    }
    return 0;
}

/* Process an authentication request.
 * Allocates a session, dispatches AUTH event, and on success
 * stores the token. On any failure, cleans up the session. */
int process_auth_request(const char *token, size_t token_len,
                         const char *user_data, size_t data_len) {
    if (validate_token(token, token_len) != 0) return -1;
    if (data_len > 255) return -1;

    session_t *sess = session_alloc();
    if (!sess) return -1;

    /* Copy user data into session */
    memcpy(sess->user_data, user_data, data_len);
    sess->user_data[data_len] = '\0';

    /* Dispatch authentication event - we own the ref */
    int rc = dispatch_event(sess, 1, (void *)token);
    if (rc < 0) {
        /* Auth failed - clean up our reference */
        session_unref(sess);
        return rc;
    }

    /* Store token on success */
    memcpy(sess->token, token, token_len);
    return (int)sess->session_id;
}

/* Renew an existing session's token */
int process_renew_request(uint32_t session_id, const char *new_token,
                          size_t token_len) {
    if (validate_token(new_token, token_len) != 0) return -1;

    session_t *sess = session_find_by_id(session_id);
    if (!sess) return -1;

    /* Dispatch renewal event */
    int rc = dispatch_event(sess, 2, (void *)new_token);
    if (rc < 0) {
        /* Renewal failed - release our lookup ref */
        session_unref(sess);
        return rc;
    }

    memcpy(sess->token, new_token, token_len);
    session_unref(sess); /* release lookup ref */
    return 0;
}

/* Example handler that rejects tokens starting with '0' */
int security_policy_handler(session_t *sess, int event_type, void *data) {
    (void)sess;
    (void)event_type;
    const char *token = (const char *)data;
    if (token && token[0] == '0') return -1;
    return 0;
}

int main(int argc, char **argv) {
    pool_init();
    register_handler(security_policy_handler);

    if (argc < 3) {
        printf("Usage: %s <token> <userdata>\n", argv[0]);
        return 1;
    }

    const char *token = argv[1];
    const char *udata = argv[2];

    int sid = process_auth_request(token, strlen(token), udata, strlen(udata));
    if (sid < 0) {
        printf("Auth failed\n");
        return 1;
    }
    printf("Session %d created\n", sid);

    /* Try renewal with a bad token to trigger error path */
    int rc = process_renew_request((uint32_t)sid, "0badtoken", 9);
    printf("Renew result: %d\n", rc);

    /* Try to use the session again */
    session_t *s = session_find_by_id((uint32_t)sid);
    if (s) {
        printf("Session still active: %s\n", s->user_data);
        session_unref(s);
    } else {
        printf("Session not found\n");
    }

    return 0;
}
